import{_ as a,o as r,c as o,a2 as s}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"案例 06 · Kalshi NBA 决赛 AI 广告（逆向拆解）","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"cases/case-06-kalshi-veo.md","filePath":"cases/case-06-kalshi-veo.md","lastUpdated":1786503105000}'),e={name:"cases/case-06-kalshi-veo.md"};function n(d,t,l,i,p,h){return r(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="案例-06-·-kalshi-nba-决赛-ai-广告-逆向拆解" tabindex="-1">案例 06 · Kalshi NBA 决赛 AI 广告（逆向拆解） <a class="header-anchor" href="#案例-06-·-kalshi-nba-决赛-ai-广告-逆向拆解" aria-label="Permalink to &quot;案例 06 · Kalshi NBA 决赛 AI 广告（逆向拆解）&quot;">​</a></h1><blockquote><p><strong>一句话</strong>：300–400 次生成换 15 条可用素材——<strong>AI 广告真实的出片率长这样</strong>。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">先说清楚这篇的性质</p><p>这是对<strong>第三方公开案例的生产模式拆解</strong>，不是项目复盘，也<strong>不是画面级拆解</strong>。</p><ul><li>原片是预测市场平台 Kalshi 的 30 秒电视广告，创作者 PJ Accetturo（@PJaccetturo）独立完成。</li><li><strong>本文作者未观看原片。<strong>所有内容基于创作者本人公开的制作说明与多家媒体报道，因此</strong>不做分镜时间轴、镜头切点、声音设计的分析</strong>——那些需要看过片子才能写。</li><li>数字为<strong>创作者对外口径</strong>，未经第三方核实。引用时请标注来源。</li><li>品牌与平台名称仅用于指称分析对象。</li></ul></div><div class="tip custom-block"><p class="custom-block-title">它和案例 05 的区别</p><p>两篇都是逆向的，但拆的东西不同：</p><ul><li><a href="/cases/case-05-lays-ai-video">案例 05 · 乐事薯片</a> 拆的是<strong>成片</strong>——分镜、节奏、哪里露馅。</li><li>本篇拆的是<strong>生产模式</strong>——出片率、链路、单人能扛多少活。</li></ul><p>**看得见成片就拆成片，只看得见流程就拆流程。**两种都有价值，别硬凑自己没有的信息。</p></div><div class="danger custom-block"><p class="custom-block-title">时间说明</p><p>原片于 <strong>2025 年 6 月</strong> NBA 决赛期间播出，<strong>不是最新案例</strong>。</p><p>之所以仍然值得单开一篇：它是<strong>公开度最高的 AI 广告制作记录</strong>——创作者把 prompt、流程、失败率全部公开了，至今没有同量级的替代品。多数品牌案例只公布结果，不公布过程。</p><p><strong>工具版本已经迭代多轮，但它暴露的生产规律没有过时。</strong></p></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>品类</td><td>预测市场 App</td></tr><tr><td>交付形态</td><td>30 秒电视广告</td></tr><tr><td>投放渠道</td><td>NBA 决赛电视贴片 + 社媒</td></tr><tr><td>制作团队</td><td><strong>1 人</strong></td></tr><tr><td>工期</td><td>约 2–3 天</td></tr><tr><td>成本</td><td>约 $2,000</td></tr><tr><td>出片率</td><td><strong>生成 300–400 条 / 采用 15 条</strong></td></tr><tr><td>传播</td><td>约 2,000 万次曝光（多渠道合计）</td></tr></tbody></table><hr><h2 id="_1-创意点" tabindex="-1">① 创意点 <a class="header-anchor" href="#_1-创意点" aria-label="Permalink to &quot;① 创意点&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>预测市场平台要在 NBA 决赛这种<strong>最贵的电视时段</strong>投广告，但显然没有传统 TVC 的预算。</p><h3 id="创意方向" tabindex="-1">创意方向 <a class="header-anchor" href="#创意方向" aria-label="Permalink to &quot;创意方向&quot;">​</a></h3><p>不走精致路线，走<strong>癫狂路线</strong>。公开描述里的画面包括：农民漂在一池鸡蛋里、外星人灌啤酒、披着美国国旗的老人大喊&quot;Indiana gonna win baby&quot;。</p><h3 id="为什么这个方向是对的" tabindex="-1">为什么这个方向是对的 <a class="header-anchor" href="#为什么这个方向是对的" aria-label="Permalink to &quot;为什么这个方向是对的&quot;">​</a></h3><p>这不是审美选择，是<strong>对工具短板的正面规避</strong>：</p><table tabindex="0"><thead><tr><th>传统 TVC 要什么</th><th>AI 当时给不了</th><th>癫狂路线要什么</th></tr></thead><tbody><tr><td>表演细腻、情绪连贯</td><td>给不了</td><td>不需要——夸张本身就是风格</td></tr><tr><td>画面精致、逻辑自洽</td><td>勉强</td><td><strong>不需要——荒诞是卖点</strong></td></tr><tr><td>人物一致性</td><td>弱</td><td>每个镜头换一个怪人，<strong>根本不需要一致</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">这是整个案例最值得学的一处判断</p><p><strong>它选了一个「AI 的缺陷会被读成风格」的创意方向。</strong></p><p>超现实、快切、每镜换人换景——AI 在这些地方的不稳定，观众读作&quot;故意做得离谱&quot;，而不是&quot;做坏了&quot;。</p><p>换成一支温情家庭片，同样的技术水平会全线暴露。<strong>创意方向和工具能力必须匹配</strong>，这是 <a href="/method/ad-formats">片型图谱</a> 里「片型是被排除出来的」在具体项目上的样子。</p></div><hr><h2 id="_2-生成链路" tabindex="-1">② 生成链路 <a class="header-anchor" href="#_2-生成链路" aria-label="Permalink to &quot;② 生成链路&quot;">​</a></h2><h3 id="四步流程" tabindex="-1">四步流程 <a class="header-anchor" href="#四步流程" aria-label="Permalink to &quot;四步流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 人写粗脚本</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>② Gemini 拆 shot list + 生成 prompt（每次只要 5 条）</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>③ Veo 3 逐条渲染（300–400 次）</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>④ CapCut / Premiere 剪辑 + 音画修补</span></span></code></pre></div><p>注意这条链路里<strong>人只在头尾出现</strong>：开头定创意，结尾做剪辑和品控。中间两段是 AI 的活。这与 <a href="/method/workflow-sop">完整链路 SOP</a> 里「AI 参与度中间高、两头低」的判断完全一致。</p><h3 id="数字" tabindex="-1">数字 <a class="header-anchor" href="#数字" aria-label="Permalink to &quot;数字&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td>总生成</td><td>300–400 条</td><td></td></tr><tr><td>最终采用</td><td>15 条</td><td></td></tr><tr><td><strong>采用率</strong></td><td><strong>约 4%</strong></td><td>即 <strong>25 条里挑 1 条</strong></td></tr><tr><td>人力</td><td>1 人</td><td>无摄制组、无演员、无场地</td></tr><tr><td>成本降幅</td><td>约 95%（对比传统制作）</td><td>创作者口径</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">4% 这个数字要正着看</p><p>这不是「效率低」，恰恰相反——**在两天内做 300 次尝试，本身就是传统流程做不到的事。**实拍连 3 次都做不到。</p><p>但它也意味着：**「AI 一次出片」是幻觉。**真实工作流是大量的生成—筛选—重生成。</p><p><a href="/guide/landscape">AI 创意广告全景</a> 里写「做 8 个镜头，生成三四十条素材是正常的」——**按这个案例，那个估计偏保守了一个量级。**做 15 个镜头，实际要生成 300–400 条。排期和成本都要按这个量级算。</p></div><hr><h2 id="_3-两个关键手法" tabindex="-1">③ 两个关键手法 <a class="header-anchor" href="#_3-两个关键手法" aria-label="Permalink to &quot;③ 两个关键手法&quot;">​</a></h2><p>创作者公开的做法里，有两条是<strong>方法级</strong>的，值得单独拎出来。</p><h3 id="手法一-一次只让模型出-5-条-prompt" tabindex="-1">手法一：一次只让模型出 5 条 prompt <a class="header-anchor" href="#手法一-一次只让模型出-5-条-prompt" aria-label="Permalink to &quot;手法一：一次只让模型出 5 条 prompt&quot;">​</a></h3><p><strong>做法</strong>：让 Gemini 生成 prompt 列表时，每次只要 5 条。</p><p><strong>理由</strong>：超过 5 条，<strong>质量开始下滑</strong>。</p><div class="warning custom-block"><p class="custom-block-title">这一条直接修正了本知识库的一处写法</p><p><a href="/pipelines/codex-gemini">Codex + Gemini Flow 流水线</a> 那篇里，我给的指令是「为每个镜头生成一个 prompt 文件」——一次 12 条。</p><p>**按这个案例的经验，一次 12 条会掉质量。**正确做法是分批，每批 5 条，批与批之间人过一眼。</p><p>这一条已经反向修正到那篇里。<strong>这就是逆向拆解的价值：别人踩过的坑，能直接改你自己的流程。</strong></p></div><h3 id="手法二-每条-prompt-完整自描述-不要引用上下文" tabindex="-1">手法二：每条 prompt 完整自描述，不要引用上下文 <a class="header-anchor" href="#手法二-每条-prompt-完整自描述-不要引用上下文" aria-label="Permalink to &quot;手法二：每条 prompt 完整自描述，不要引用上下文&quot;">​</a></h3><p><strong>做法</strong>：每条 prompt 都<strong>假设模型完全不知道前后镜头</strong>，把场景、角色、语气<strong>从头到尾重新描述一遍</strong>。</p><p><strong>理由</strong>：这是维持跨镜头一致性的手段。模型没有上下文记忆，你以为的&quot;承接上一镜&quot;，它读不到。</p><div class="tip custom-block"><p class="custom-block-title">和知识库既有方法的交叉验证</p><p>这与 <a href="/prompts/structure">Prompt 结构通法</a> 的五段式、以及 <a href="/method/brand-consistency">品牌一致性控制</a> 的「风格描述固化」是<strong>同一个原则的两种实现</strong>：</p><blockquote><p><strong>信息冗余优于引用。</strong></p></blockquote><p>手工做法是每条都重打一遍（累，且容易漏字）；工程化做法是把风格段抽成文件，生成时自动拼到每条前面（见 <a href="/pipelines/codex-gemini">流水线</a>）。</p><p><strong>两条路殊途同归——独立得出的相同结论，可信度比任何单一来源都高。</strong></p></div><hr><h2 id="_4-可复用套路" tabindex="-1">④ 可复用套路 <a class="header-anchor" href="#_4-可复用套路" aria-label="Permalink to &quot;④ 可复用套路&quot;">​</a></h2><ol><li><p>**让创意方向去适配工具短板，而不是让工具去硬扛创意。**荒诞风格能把&quot;不稳定&quot;读成&quot;风格&quot;，温情叙事不能。选片型时把这一条算进去。</p></li><li><p>**出片率按 4% 估，不要按 50% 估。**报价、排期、消耗预算全部按&quot;25 条里挑 1 条&quot;倒推。这是这个案例最硬的一条数据。</p></li><li><p>**prompt 分批生成，每批 5 条。**批量不等于一次性。</p></li><li><p>**每条 prompt 完整自描述。**不要写&quot;同上一镜的场景&quot;，模型读不到。</p></li><li><p>**剪辑用传统软件。**创作者用的是 CapCut 和 Premiere——**AI 负责生成素材，成片的节奏和品控仍然靠人和老工具。**这与 <a href="/tools/landscape">工具全景对照表</a> 对第⑤类工具的判断一致。</p></li><li><p><strong>单人可以扛完一支电视广告。<strong>这是这个案例最反直觉的结论——不是&quot;团队用 AI 提效&quot;，是</strong>&quot;编制被重构了&quot;</strong>。</p></li></ol><hr><h2 id="边界-它不能证明什么" tabindex="-1">边界：它不能证明什么 <a class="header-anchor" href="#边界-它不能证明什么" aria-label="Permalink to &quot;边界：它不能证明什么&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">别过度外推</p><p>这个案例经常被当作&quot;AI 广告已经成熟&quot;的证据，但它成立有<strong>前置条件</strong>：</p><table tabindex="0"><thead><tr><th>它证明了</th><th>它没有证明</th></tr></thead><tbody><tr><td>荒诞风格能低成本做出来</td><td>精致品牌片能低成本做出来</td></tr><tr><td>单人能扛一支 30 秒片</td><td>单人能扛一支有表演的叙事片</td></tr><tr><td>2 天能出片</td><td><strong>任何</strong>创意 2 天都能出片</td></tr><tr><td>这条创意有效</td><td>这套打法可无限复制</td></tr></tbody></table><p>**尤其是最后一条。**它的传播效果里，有相当一部分来自&quot;这是 AI 做的&quot;这个新闻性本身。<strong>同样的片子今天再做一支，不会再有这个红利。</strong></p></div><hr><h2 id="如果我来做这个项目-最想改的一件事" tabindex="-1">如果我来做这个项目，最想改的一件事 <a class="header-anchor" href="#如果我来做这个项目-最想改的一件事" aria-label="Permalink to &quot;如果我来做这个项目，最想改的一件事&quot;">​</a></h2><p><strong>建立筛选台账。</strong></p><p>300–400 条素材靠人肉记忆管理，是这条链路里最脆的一环。哪条已经看过、哪条为什么废、同一镜头的第几版最好——不记下来，两天后自己都分不清。</p><p>这正是 <a href="/pipelines/codex-gemini">Codex + Gemini Flow 流水线</a> 那篇要解决的问题：<strong>生成不是瓶颈，管理 300 个废片才是。</strong></p><hr><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本文的观察</th><th>对应的方法</th></tr></thead><tbody><tr><td>出片率 4%，管理 300 条素材</td><td><a href="/pipelines/codex-gemini">Codex + Gemini Flow 流水线</a></td></tr><tr><td>创意方向要匹配工具能力</td><td><a href="/method/ad-formats">片型图谱</a></td></tr><tr><td>prompt 完整自描述维持一致性</td><td><a href="/prompts/structure">Prompt 结构通法</a>、<a href="/method/brand-consistency">品牌一致性控制</a></td></tr><tr><td>人在头尾、AI 在中间</td><td><a href="/method/workflow-sop">完整链路 SOP</a></td></tr><tr><td>剪辑仍靠传统软件</td><td><a href="/tools/landscape">全景对照表 · ⑤剪辑与后期</a></td></tr><tr><td>另一种逆向拆解的读法</td><td><a href="/cases/case-05-lays-ai-video">案例 05 · 乐事薯片</a></td></tr></tbody></table><p><strong>参考来源</strong>：<a href="https://twitter.com/PJaccetturo/status/1932893260399456513" target="_blank" rel="noreferrer">创作者本人的流程说明（X）</a> · <a href="https://www.yahoo.com/entertainment/articles/chaotic-kalshi-ad-during-nba-173937071.html" target="_blank" rel="noreferrer">Business Insider / Yahoo 报道</a> · <a href="https://www.marktechpost.com/2025/06/14/ai-generated-ad-created-with-googles-veo3-airs-during-nba-finals-slashing-production-costs-by-95/" target="_blank" rel="noreferrer">MarkTechPost</a> · <a href="https://www.eweek.com/news/ai-ad-kalshi-nba-finals/" target="_blank" rel="noreferrer">eWeek</a></p>`,50)])])}const u=a(e,[["render",n]]);export{g as __pageData,u as default};
